using System.ComponentModel.DataAnnotations; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using OrcaFacil.Web.Security;
namespace OrcaFacil.Web.Pages.Auth;
[AllowAnonymous] public sealed class ResetPasswordModel(IPasswordRecoveryService recovery):PageModel { [BindProperty(SupportsGet=true)] public string Token{get;set;}=""; [BindProperty,Required,MinLength(8)] public string Password{get;set;}=""; [BindProperty,Required,Compare(nameof(Password))] public string Confirmation{get;set;}=""; public bool Available{get;set;} public async Task OnGetAsync(CancellationToken ct)=>Available=await recovery.IsTokenValidAsync(Token,ct); public async Task<IActionResult> OnPostAsync(CancellationToken ct){Available=await recovery.IsTokenValidAsync(Token,ct);if(!Available)return Page();if(!ModelState.IsValid)return Page();if(!await recovery.ResetAsync(Token,Password,ct)){Available=false;return Page();}return RedirectToPage("/Auth/ResetPasswordConfirmation");}}
